function validate([points]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 10) return 'points needs 1 to 10 points.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is [x, y].';
    if (!p.every(v => Number.isInteger(v) && v >= -100 && v <= 100)) return 'Coordinates are integers from -100 to 100.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  return null;
}

