function minimumLines(points) {
  const n = points.length;
  const full = (1 << n) - 1;
  const lineMask = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const dx = points[j][0] - points[i][0];
      const dy = points[j][1] - points[i][1];
      let mask = 0;
      for (let p = 0; p < n; p++) {
        const cross = dx * (points[p][1] - points[i][1]) - dy * (points[p][0] - points[i][0]);
        if (cross === 0) mask |= 1 << p;
      }
      lineMask[i][j] = mask;
      lineMask[j][i] = mask;
    }
  }
  const dp = new Array(full + 1).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    if (dp[mask] === Infinity) continue;
    let first = 0;
    while (mask & (1 << first)) first++;
    const alone = mask | (1 << first);
    dp[alone] = Math.min(dp[alone], dp[mask] + 1);
    for (let j = 0; j < n; j++) {
      if (mask & (1 << j) || j === first) continue;
      const next = mask | lineMask[first][j];
      dp[next] = Math.min(dp[next], dp[mask] + 1);
    }
  }
  return dp[full];
}

