function minimumLines(points) {
  const n = points.length;
  const onLine = (a, b, c) => (b[0] - a[0]) * (c[1] - a[1]) === (b[1] - a[1]) * (c[0] - a[0]);
  // Try to split the points into at most `limit` collinear groups by backtracking.
  const fits = (limit) => {
    const groups = [];
    const place = (p) => {
      if (p === n) return true;
      for (const g of groups) {
        if (g.length >= 2 && !onLine(g[0], g[1], points[p])) continue;
        g.push(points[p]);
        if (place(p + 1)) return true;
        g.pop();
      }
      if (groups.length < limit) {
        groups.push([points[p]]);
        if (place(p + 1)) return true;
        groups.pop();
      }
      return false;
    };
    return place(0);
  };
  for (let limit = 1; ; limit++) if (fits(limit)) return limit;
}

