function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 10 : 1 + Math.floor(rand() * 8);
  const span = large ? 100 : 1 + Math.floor(rand() * 4);
  const seen = new Set();
  const points = [];
  const add = (x, y) => {
    if (x < -span || x > span || y < -span || y > span) return;
    const key = x + ',' + y;
    if (seen.has(key) || points.length >= n) return;
    seen.add(key);
    points.push([x, y]);
  };
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Lay some points along a few random lines so that collinear groups are common.
  const lines = pick(0, large ? 4 : 3);
  for (let t = 0; t < lines && points.length < n; t++) {
    const x0 = pick(-span, span), y0 = pick(-span, span);
    const dx = pick(-3, 3), dy = pick(-3, 3);
    if (dx === 0 && dy === 0) continue;
    const count = pick(2, large ? 5 : 4);
    for (let s = 0; s < count; s++) {
      const step = pick(-Math.floor(span / 3) - 1, Math.floor(span / 3) + 1);
      add(x0 + dx * step, y0 + dy * step);
    }
  }
  while (points.length < n) add(pick(-span, span), pick(-span, span));
  for (let i = points.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [points[i], points[j]] = [points[j], points[i]];
  }
  return [points];
}
